#pragma once
inline nlohmann::json rendering109Proof(hb::gpu::Device& gpu,const std::string& fixture){
 using namespace hb::gpu;std::ifstream input(fixture);const auto packets=nlohmann::json::parse(input).at("rendering109");SceneRenderer r(gpu,64,64);SceneFrame frame;frame.clear={0,0,0,1};frame.eye={0,0,-1,1};frame.screenEffects.emplace();auto& s=*frame.screenEffects;s.path={1,4,16,0};s.pathQuality={4,0,0,0};s.pathEnvironment={0,0,0,64};s.pathLens={0,4,0,0};s.camera={.1f,100,1,1};s.eye={0,0,-1,1};s.geometry={0,20,1,4};s.inverseVP=identity;
 auto visible=r.createMesh({{{-1,-1,.6f},{0,0,-1}},{{1,-1,.6f},{0,0,-1}},{{1,1,.6f},{0,0,-1}},{{-1,1,.6f},{0,0,-1}}},{0,1,2,0,2,3});SceneMaterial black;black.unlit=true;black.color={0,0,0,1};nlohmann::json proof;
 for(const std::string kind:{"primary","primaryWorld","glass","mirror"})for(const std::string mode:{"raw","mip"}){const auto& p=packets.at(kind+"_"+mode);const auto data=p.at("data").get<std::vector<float>>();std::vector<std::uint8_t> bytes(data.size()*4);std::memcpy(bytes.data(),data.data(),bytes.size());auto world=r.createDataTexture(p.at("width").get<UINT>(),p.at("height").get<UINT>(),bytes,4,true);s.rayPrograms=readRayPrograms(p.at("rayPrograms"));s.geometryInfo={p.at("width"),p.at("height"),p.at("nodeCount"),p.at("triangleOffset")};s.geometryLimits={256,.001f,p.at("lightsOffset"),p.at("lightCount")};s.transport={p.at("materialsOffset"),2,1,32};s.pathQuality={4,p.at("emitterOffset"),p.at("emitterCount"),p.at("operationMask")[2]};s.pathLens[2]=p.at("operationMask")[0];s.pathLens[3]=p.at("operationMask")[1];r.setGeometryScene(&world);std::vector<std::uint8_t> rgba;
  for(int n=0;n<4;n++){s.path[3]=float(n*4);r.begin(frame);r.draw(visible,identity,identity,black);rgba=r.readPixels();}double sum=0,sum2=0;for(int y=16;y<48;y++)for(int x=16;x<48;x++){double v=rgba[(y*64+x)*4];sum+=v;sum2+=v*v;}const double mean=sum/1024,variance=sum2/1024-mean*mean;proof[kind][mode]={{"mean",mean},{"variance",variance}};r.setGeometryScene(nullptr);
 }
 std::ofstream(fixture+".109.json")<<proof.dump(2);
 for(const std::string kind:{"primary","primaryWorld","glass","mirror"}){const double raw=proof[kind]["raw"]["variance"],filtered=proof[kind]["mip"]["variance"],mean=proof[kind]["mip"]["mean"];assert(raw>20);assert(filtered<raw*.75);assert(mean>25&&mean<240);}frame.screenEffects.reset();r.begin(frame);assert(r.bloomTextureBytes()==0);proof["passed"]=true;proof["actualHLSLBytecode"]=true;proof["primaryReflectionRefraction"]=true;proof["disabledResourcesZero"]=true;return proof;
}
